CREATE DATABASE vlexplosion_test CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vlexplosion_test;
CREATE TABLE Users_TBL (id INT PRIMARY KEY, username VARCHAR(32) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, email VARCHAR(254) UNIQUE NOT NULL) ENGINE=InnoDB;
INSERT INTO Users_TBL VALUES (7,'fiction','fiction','fiction@example.invalid'),(8,'other','fiction','other@example.invalid');
CREATE TABLE AUTHORS_TBL (Id INT PRIMARY KEY AUTO_INCREMENT, Author_Name VARCHAR(50) NOT NULL) ENGINE=InnoDB;
CREATE TABLE GENRES_TBL (Id INT PRIMARY KEY, Genre_Name VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE FORMAT_TBL (Id INT PRIMARY KEY, Format_Name VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE CONDITION_TBL (Id INT PRIMARY KEY, Condition_Name VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE RECORD_LABEL_TBL (Id INT PRIMARY KEY, Record_Label_Name VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE EDITION_TBL (Id INT PRIMARY KEY, Edition_Name VARCHAR(30) NOT NULL) ENGINE=InnoDB;
INSERT INTO GENRES_TBL VALUES (1,'Fiction'); INSERT INTO FORMAT_TBL VALUES (1,'Fiction'); INSERT INTO CONDITION_TBL VALUES (1,'Fiction'); INSERT INTO RECORD_LABEL_TBL VALUES (1,'Fiction'); INSERT INTO EDITION_TBL VALUES (1,'Fiction');
CREATE TABLE VINYLS_TBL (Id INT PRIMARY KEY AUTO_INCREMENT, Title VARCHAR(65) NOT NULL, Genres_Id INT NOT NULL, Format_Id INT NOT NULL, Condition_Id INT NOT NULL, Record_Label_Id INT NOT NULL, Producer VARCHAR(50) NOT NULL, Release_date YEAR NOT NULL, Edition_Id INT NOT NULL, User_Id INT NOT NULL, Is_Favorite TINYINT DEFAULT 0, Is_Desired TINYINT DEFAULT 0, Image_Path VARCHAR(255), FOREIGN KEY (Genres_Id) REFERENCES GENRES_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (Format_Id) REFERENCES FORMAT_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (Condition_Id) REFERENCES CONDITION_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (Record_Label_Id) REFERENCES RECORD_LABEL_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (Edition_Id) REFERENCES EDITION_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (User_Id) REFERENCES Users_TBL(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE AUTOR_VINYLS_TBL (Autor_Id INT NOT NULL, Vinilo_Id INT NOT NULL, PRIMARY KEY (Autor_Id,Vinilo_Id), FOREIGN KEY (Autor_Id) REFERENCES AUTHORS_TBL(Id) ON DELETE CASCADE, FOREIGN KEY (Vinilo_Id) REFERENCES VINYLS_TBL(Id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE USER 'test_runner'@'localhost' IDENTIFIED BY '';
GRANT SELECT, INSERT, UPDATE, DELETE ON vlexplosion_test.* TO 'test_runner'@'localhost';

CREATE TRIGGER fail_fiction BEFORE INSERT ON VINYLS_TBL FOR EACH ROW SET NEW.Title = IF(NEW.Title='HTTP rollback upload', NULL, NEW.Title);
